#!/usr/bin/env bash
# PURPOSE   Deploy the Entity Framework project to a local SQL Server container, the same way the EF
#           migrations would be applied elsewhere (an idempotent SQL script generated by `dotnet ef`).
#           This database is ALSO Flyway's "development" database: the Flyway schema model is updated from it
#           (see UpdateFlywaySchemaModel.sh). It lives in its own container, so whatever you normally use for
#           development is unaffected.
#
# USAGE     ./Scripts/DockerDeployFromEntityFrameworkIdempotentScript.sh
#
# NEEDS     Docker, the .NET 8 SDK + dotnet-ef (Scripts/SetupDockerOverWSL.sh and SetupDotnetPrerequisites.sh
#           install them), and MSSQL_SA_PASSWORD.
# DATABASE  <base>_<branch>, e.g. EntityFrameworkDemo_featureaddwidgets. Created if missing. Override with
#           MSSQL_DATABASE_NAME. See lib/common.sh (database naming) for the rule shared with Flyway.
# SETTINGS  MSSQL_SA_PASSWORD (required), MSSQL_DATABASE_NAME, MSSQL_DATABASE_BASE, MSSQL_CONTAINER_NAME,
#           MSSQL_PORT, MSSQL_IMAGE, DOCKER. See lib/common.sh, section 1.
# EXIT      0 deployed.  2 couldn't run (missing prerequisite, bad setting, SQL error).
set -euo pipefail

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib/common.sh
source "$script_dir/lib/common.sh"

require_docker
require_dotnet_ef
require_sql_password

database_name="$(resolve_database_name)"
validate_database_name "$database_name"

sql_script="$(mktemp)"
trap 'rm -f "$sql_script"' EXIT

ensure_sql_container
ensure_database "$database_name"

# The EF design-time factory (EntityFramework/Data/AppDbContextFactory.cs) reads these to build its connection string.
export MSSQL_PORT="$SQL_PORT"
export MSSQL_DATABASE_NAME="$database_name"
dotnet ef migrations script --idempotent --output "$sql_script" --project "$REPO_DIR/EntityFramework"
sed -i '1s/^\xEF\xBB\xBF//' "$sql_script"      # strip the UTF-8 BOM, which sqlcmd would choke on
sqlcmd_exec "$database_name" <"$sql_script"

echo "Deployed Entity Framework idempotent migration script to database '$database_name'."
